        HttpRequest request = HttpRequest.newBuilder(URI.create(url))
                .GET()
                .setOption(HttpOption.H3_DISCOVERY, HttpOption.Http3DiscoveryMode.HTTP_3_URI_ONLY)
                .build();
        return client.send(request, BodyHandlers.ofString());
    }
}

