        if (!super.equals(o)) return false;
        Customer customer = (Customer) o;
        return Objects.equals(loyaltyCardId, customer.loyaltyCardId);
    }

    @Override
    public int hashCode() {
        return Objects.hash(super.hashCode(), loyaltyCardId);
    }
}

